  "facts": {
   "name": "facts",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "negotiate",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\n\ndef parse_now(value):\n    \"\"\"'2031-03-07T11:00', '2031-03-07 11:00:00', '2031-03-07T11:00:00Z' or '2031-03-07' -> datetime.\"\"\"\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now: ' + s)\n\ndef parse_holidays(values):\n    \"\"\"ISO strings -> set of dates. Unreadable entries are skipped.\"\"\"\n    out = set()\n    for v in values or []:\n        try:\n            out.add(datetime.date.fromisoformat(str(v)[:10]))\n        except ValueError:\n            pass\n    return out\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    \"\"\"The first business day after d (or d itself when include_today and d is one).\"\"\"\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef add_business_days(d, n, holidays):\n    \"\"\"The n-th business day after d (d itself not counted). n=0 returns d.\"\"\"\n    for _ in range(int(n)):\n        d = next_business_day(d, holidays)\n    return d\n\ndef week_monday(d):\n    return d - datetime.timedelta(days=d.weekday())\n\ndef last_business_day_of_week(d, holidays):\n    \"\"\"The last business day in d's Monday-Sunday week, or None when the week has none.\"\"\"\n    day = week_monday(d) + datetime.timedelta(days=4)\n    while day >= week_monday(d):\n        if is_business_day(day, holidays):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef spoken_date(d):\n    \"\"\"'Friday 7 March'. Adapt the words to the brief's language.\"\"\"\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(amount, symbol=''):\n    \"\"\"1234.5 -> '1,234.50' (with an optional symbol in front). 1234.0 -> '1,234'.\"\"\"\n    v = round(float(amount), 2)\n    text = '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)\n    return symbol + text\n\ndef list_from_vars(vars, name, prefixes):\n    \"\"\"A list from an API result, wherever the platform put it. Seen in a practice run on 10 October: a node-level\n    response_mapping of a list left the variable unset; the list existed only as flattened keys such as\n    '<node id>_response.data.<field>.0.<key>'. Tries vars[name] first, then each flattened prefix\n    (e.g. 'load_account_response.data.items' or 'get_account_response.data.items'), in index order.\"\"\"\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = {}\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            rest = str(key)[len(start):]\n            idx, _, field = rest.partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), {})[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\n\ndef as_list(value):\n    \"\"\"A mapped list may arrive as a list, a JSON string or a dict (tools-and-code.md): always return a list.\"\"\"\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\n\nBANDS = [(1, 20, 5, 1), (21, 60, 3, 2)]  # days_over from, to, deadline in business days, attempts (invented)\ntry:\n    now = parse_now(vars.get('now'))\n    hol = parse_holidays(['2031-03-14', '2031-04-02'])\n    today = now.date()\n    items = list_from_vars(vars, 'items', ['load_account_response.data.items', 'get_account_response.data.items'])\n    lines, facts, offers = [], [], []\n    for n, it in enumerate(items, 1):\n        days = int(it.get('days_over') or 0)\n        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])\n        deadline = add_business_days(today, band[2], hol)\n        week_end = last_business_day_of_week(today, hol)\n        if week_end is None or week_end <= today:\n            week_end = last_business_day_of_week(today + datetime.timedelta(days=7), hol)\n        attempt1 = min(week_end, deadline) if week_end else deadline\n        name = 'item ending ' + str(it.get('ending')) if it.get('kind') == 'kind_a' else 'second item'\n        facts.append(dict(ref=it.get('item_ref'), name=name, overdue=it.get('overdue'), floor=it.get('floor_amount'),\n                          deadline=deadline.isoformat(), attempts=band[3], attempt1=attempt1.isoformat()))\n        offers.append('- Lower amount for ' + name + ': \"Could you pay ' + money(it.get('floor_amount') or 0) + ' by ' +\n                      spoken_date(attempt1) + '? The remaining amount stays open on this item.\"')\n        lines.append(str(n) + '. ' + name + ' (item_ref ' + str(it.get('item_ref')) + '): ' + money(it.get('overdue') or 0) +\n                     ' overdue, ' + str(days) + ' days late. Lowest amount: ' + money(it.get('floor_amount') or 0) +\n                     '. Latest date: ' + spoken_date(deadline) + ' (' + deadline.isoformat() + '). Attempts: ' + str(band[3]) +\n                     '. Attempt 1 date: ' + spoken_date(attempt1) + ' (' + attempt1.isoformat() + ').')\n    vars['facts_text'] = ('Today is ' + spoken_date(today) + '.\\n' + '\\n'.join(lines) +\n                          '\\nSay these sentences exactly when they apply:\\n' + '\\n'.join(offers))\n    vars['facts_json'] = json.dumps(facts)\n    # The proposal sequence per item, in the bank's order, as complete sentences. The offer loop speaks them; the\n    # model never decides how many attempts are left. (Example Bank: attempt 1 = full amount on the attempt-1 date,\n    # attempt 2 = the lowest amount on the latest date, only for items allowed 2 attempts.)\n    offer_list = []\n    for f in facts:\n        a1, dl = datetime.date.fromisoformat(f['attempt1']), datetime.date.fromisoformat(f['deadline'])\n        steps = [dict(text='For your ' + f['name'] + ', could you pay ' + money(f['overdue'] or 0) + ' by ' + spoken_date(a1) + '?',\n                      amount=f['overdue'], date=f['attempt1'])]\n        if f['attempts'] >= 2:\n            steps.append(dict(text='Could you pay ' + money(f['floor'] or 0) + ' by ' + spoken_date(dl) +\n                              '? The remaining amount stays open on this item.', amount=f['floor'], date=f['deadline']))\n        offer_list.append(dict(ref=f['ref'], name=f['name'], steps=steps))\n    vars['offers_json'] = json.dumps(offer_list)\n    vars['offer_item'] = '0'\n    vars['offer_step'] = '0'\n    vars['offer_answer'] = 'stay'\n    vars['loop_event'] = 'start'\n    vars['agreements_json'] = '[]'\n    vars['item_count'] = str(len(facts))\n    vars['facts_state'] = 'ok' if facts else 'empty'\nexcept Exception:\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['facts_json'] = '[]'\n    vars['offers_json'] = '[]'\n    vars['item_count'] = '0'\n    vars['facts_state'] = 'error'\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "negotiate",
     "description": "always",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
