\n        vars['offer_amount'] = str(s['amount'])\n        vars['offer_date'] = s['date']\n        vars['offer_ref'] = offers[item]['ref']\n    vars['offer_item'] = str(item)\n    vars['offer_step'] = str(step)\nexcept Exception:\n    vars['offer_state'] = 'done'\n"
