   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\nimport json\n\nHOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\nGUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']\nAY = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']\nONE = datetime.timedelta(days=1)\n\ndef sp(d):\n    return str(d.day) + ' ' + AY[d.month - 1] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]\n\ndef isb(d):\n    return d.weekday() < 5 and d.isoformat() not in HOL\n\ndef nxt(d):\n    d = d + ONE\n    while not isb(d):\n        d = d + ONE\n    return d\n\ndef lastb(mon):\n    d = mon + datetime.timedelta(days=4)\n    while d >= mon:\n        if isb(d):\n            return d\n        d = d - ONE\n    return None\n\ndef m(v):\n    s = '{:,.2f}'.format(round(float(v), 2)).replace(',', 'X').replace('.', ',').replace('X', '.')\n    return s[:-3] if s.endswith(',00') else s\n\ndef products():\n    for pre in ('load_account_response.data.products', 'get_account_response.data.products'):\n        rows = {}\n        for k, val in vars.items():\n            k = str(k)\n            if k.startswith(pre + '.'):\n                idx, _, f = k[len(pre) + 1:].partition('.')\n                if idx.isdigit() and f:\n                    rows.setdefault(int(idx), {})[f] = val\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n    v = vars.get('products')\n    if isinstance(v, str):\n        try:\n            v = json.loads(v)\n        except ValueError:\n            v = []\n    if isinstance(v, dict):\n        v = [v]\n    return v if isinstance(v, list) else []\n\ntry:\n    now = datetime.datetime.strptime(str(vars.get('now') or '').strip().replace(' ', 'T')[:16], '%Y-%m-%dT%H:%M')\n    today = now.date()\n    p = products()[0]\n    typ = str(p.get('type'))\n    days = int(float(p.get('days_late') or 0))\n    past = float(p.get('past_due') or 0)\n    if typ == 'credit_card':\n        label = str(p.get('card_last4') or '') + ' ile biten kredi kartı'\n        floor = float(p.get('minimum_payment') or 0)\n    elif typ == 'car_loan':\n        label = 'taşıt kredisi'\n        floor = float(p.get('instalment_amount') or 0)\n    else:\n        label = 'ihtiyaç kredisi'\n        floor = float(p.get('instalment_amount') or 0)\n    n, att, band = (12, 1, 'early') if days <= 7 else (7, 2, 'late')\n    dl = today\n    for _ in range(n):\n        dl = nxt(dl)\n    mon = today - datetime.timedelta(days=today.weekday())\n    a1 = lastb(mon)\n    if a1 is None or a1 <= today:\n        a1 = lastb(mon + datetime.timedelta(days=7))\n    if a1 is None or a1 > dl:\n        a1 = dl\n    ok_days = []\n    d = today\n    while d <= dl:\n        if isb(d):\n            ok_days.append(sp(d) + ' = ' + d.isoformat())\n        d = d + ONE\n    vars['product_id'] = str(p.get('product_id') or '')\n    vars['product_label'] = label\n    vars['past_due'] = str(past)\n    vars['floor_amount'] = str(floor)\n    vars['deadline_iso'] = dl.isoformat()\n    vars['attempt1_iso'] = a1.isoformat()\n    vars['attempts'] = str(att)\n    vars['announce_text'] = ('Doğrulama için teşekkür ederim. Gecikmiş bir ödeme nedeniyle tahsilat ekibinden arıyorum. ' + label[0].upper() + label[1:] +\n        ' için ' + str(days) + ' gündür gecikmiş ' + m(past) + ' liralık vadesi geçmiş tutar var. Bu ödemeyi bugün yapabilir misiniz?')\n    lines = ['Bugün: ' + sp(today) + ' (' + today.isoformat() + ').',\n             'Ürün: ' + label + '. product_id: ' + vars['product_id'] + '.',\n             'Vadesi geçmiş tutarın tamamı: ' + m(past) + ' lira (amount ' + str(past) + ').',\n             'Taban tutar: ' + m(floor) + ' lira (amount ' + str(floor) + '). Kabul edilebilir tutar: taban tutar ile tamamı arası, ikisi dahil.',\n             'Bant: ' + band + ', ikna denemesi sayısı: ' + str(att) + '.',\n             'Son tarih: ' + sp(dl) + ' (' + dl.isoformat() + '). Bundan sonraki hiçbir tarih kaydedilemez.',\n             'Deneme 1: ' + sp(a1) + ' (' + a1.isoformat() + ') tarihinde tutarın tamamı ' + m(past) + ' lira (müşteri tamamının çok fazla olduğunu zaten söylediyse taban tutar ' + m(floor) + ' lira).']\n    if att >= 2:\n        lines.append('Deneme 2: son tarih ' + sp(dl) + ' (' + dl.isoformat() + ') tarihinde taban tutar ' + m(floor) + ' lira; kalan tutar vadesi geçmiş olarak kalır.')\n    else:\n        lines.append('Deneme 2 yok (early bant).')\n    lines.append('Söz için geçerli iş günleri (başka gün kaydedilemez): ' + '; '.join(ok_days) + '.')\n    vars['facts_text'] = '\\n'.join(lines)\n    vars['facts_state'] = 'ok'\nexcept Exception:\n    vars['facts_text'] = 'Hesap bilgileri okunamadı.'\n    vars['announce_text'] = 'Doğrulama için teşekkür ederim.'\n    vars['facts_state'] = 'error'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [
