   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": "vars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\n"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
