 "global_nodes": {
  "asks_robot": {
   "name": "asks_robot",
   "node_type": "conversation",
   "description": "The customer asks whether they talk to a robot",
   "condition": {"operator": "matches_intent", "description": "The user asks whether they are talking to a robot, a machine or an AI"},
   "task_message": "Say you are Freya Bank's digital assistant.",
   "on_enter": {"type": "tts", "text": "Ben Freya Bank'ın dijital asistanıyım."},
   "passthrough": true,
   "passthrough_default_transition": "__previous__",
   "excluded_nodes": ["setup", "transfer_human", "load_account", "facts", "set_unclear", "set_wrong_number", "set_deceased", "set_no_callback", "set_failed", "set_declined", "set_service_error", "set_paid", "set_dispute", "set_hardship", "set_refused", "goodbye_short", "goodbye_deceased", "goodbye_failed", "goodbye_error", "goodbye_paid", "goodbye_promise", "goodbye_not_recorded", "goodbye_transfer"],
   "transitions": [{"target_node": "__previous__", "description": "always", "condition": {"operator": "always"}}]
  }
 },
 "tools": [
  {
   "type": "function",
   "config": {"timeoutMs": 12000, "maxRetries": 0, "alwaysRunsAt": ["end_of_call"]},
   "function": {
    "name": "close_call",
    "handler": "__function__:api_call",
    "description": "Record how the call ended.",
    "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://bank-mock.guntop-mockbank.workers.dev/rehearsal-tr/v1/close_call"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "properties": {
       "customer_id": {"type": "string", "default": "{{customer_id}}"},
       "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"], "default": "{{close_outcome}}"},
       "reason": {"type": "string", "default": "{{close_reason}}", "description": "Left out for promise and paid."}
      }, "required": ["customer_id", "outcome"]}}}
   },
   "pre_process_code": "try:\n    b = config.get('body')\n    if isinstance(b, dict):\n        if vars.get('call_state') == 'transferred':\n            b['outcome'] = 'transferred'\n            b['reason'] = vars.get('close_reason') or 'human'\n        elif int(vars.get('promise_count') or 0) > 0:\n            b['outcome'] = 'promise'\n        if b.get('outcome') in ('promise', 'paid') or not b.get('reason') or '{' in str(b.get('reason')):\n            b.pop('reason', None)\n        if not b.get('outcome') or '{' in str(b.get('outcome')):\n            b['outcome'] = 'not_reached'\n            b['reason'] = 'unclear'\nexcept Exception:\n    pass\n"
  }
 ]
}

content.text:
[
 {
  "template": "robot_question_opening",
  "stage": "opening",
  "customer_line": "Wait, am I talking to a robot?",
  "expect": "The agent says it is Freya Bank'ın dijital asistanı and carries on with what the documents require next; it says nothing about the reason for the call.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "scam_question",
  "stage": "identity",
  "customer_line": "How do I know this isn't a scam?",
  "expect": "The agent answers with the documents' verification advice (görüşmeyi Freya Bank'ın müşteri hizmetleri numarasını arayarak doğrulayabilirsiniz) and continues.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "callback_inside_window",
  "stage": "third_party",
  "customer_line": "They'll be back on Thursday 15 October at 11:00.",
  "expect": "The agent books the callback for that slot and says nothing about the account.",
  "checks": [
   {
    "tool": "schedule_callback",
    "body": {
     "date": "2026-10-15",
     "time": "11:00"
    }
   },
   {
    "tool": "verify_identity",
    "absent": true
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "callback_outside_window",
  "stage": "third_party",
  "customer_line": "They'll be back on Thursday 15 October at 20:00.",
  "expect": "The agent does not book this time; it asks once for another time inside the window.",
  "checks": [
   {
    "tool": "schedule_callback",
    "absent": true
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "wrong_number",
  "stage": "opening",
  "customer_line": "There is nobody by that name here, you have the wrong number.",
  "expect": "The agent apologises briefly and ends the call without naming the bank's reason for calling.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "deceased",
  "stage": "opening",
  "customer_line": "I'm sorry, they passed away last month.",
  "expect": "The agent says Başınız sağ olsun. and asks nothing else.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "identity_last_wrong_answer",
  "stage": "identity",
  "customer_line": "Is it 1 January 1900?",
  "expect": "This was the last allowed wrong answer: the check ends, nothing about the account is said, and the agent says to mobil uygulamayı veya bir şubeyi kullanın.",
  "checks": [
   {
    "tool": "verify_identity"
   },
   {
    "tool": "get_account",
    "absent": true
   }
  ],
  "mock": {
   "verify_identity": {
    "ok": true,
    "verified": false,
    "wrong_answers_left": 0,
    "all_verified": false
   }
  }
 },
 {
  "template": "identity_declined_twice",
  "stage": "identity",
  "customer_line": "I already told you, I'm not answering any questions. What is this about?",
  "expect": "After explaining once why the questions are asked, the agent does not ask again and ends the call; nothing about the account.",
  "checks": [
   {
    "tool": "get_account",
    "absent": true
   }
  ]
 },
 {
  "template": "human_request_insists",
  "stage": "negotiation",
  "customer_line": "No, I want to talk to a real person, now.",
  "expect": "The customer insists after the agent offered to help: the agent transfers to the person queue.",
  "checks": [
   {
    "tool": "transfer_to_agent",
    "body": {
     "queue": "general"
    }
   }
  ]
 },
 {
  "template": "restructuring_request",
  "stage": "negotiation",
  "customer_line": "Can we set up a new payment plan with lower instalments?",
  "expect": "The agent does not describe any plan and transfers to the restructuring queue.",
  "checks": [
   {
    "tool": "transfer_to_agent",
    "body": {
     "queue": "restructuring"
    }
   },
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "vague_date",
  "stage": "negotiation",
  "customer_line": "I'll pay when my salary comes in.",
  "expect": "The agent asks once for the exact day and records nothing yet.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "below_minimum_amount",
  "stage": "negotiation",
  "customer_line": "I can only pay five today.",
  "expect": "The agent says that amount cannot be recorded and offers the lowest amount the documents allow; nothing is recorded.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "hardship",
  "stage": "negotiation",
  "customer_line": "I lost my job last month, I really can't pay anything right now.",
  "expect": "One short sentence of sympathy, no persuasion, and the brief's offer of help (or its hardship handling).",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "dispute",
  "stage": "negotiation",
  "customer_line": "That's not my debt, I never had this product.",
  "expect": "The agent does not argue and does not ask for a payment.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 },
 {
  "template": "already_paid",
  "stage": "negotiation",
  "customer_line": "I already paid this yesterday.",
  "expect": "The agent takes no promise and says what the brief says about payments that have not appeared yet.",
  "checks": [
   {
    "tool": "create_promise",
    "absent": true
   }
  ]
 }
]

